class Solution {
public:
    struct Info {
        long long sum;
        bool isBST;
        long long minVal;
        long long maxVal;
    };

    long long maxSum;

    Info dfs(TreeNode* node) {
        if (!node) {
            return {0, true, LLONG_MAX, LLONG_MIN};
        }
        Info left = dfs(node->left);
        Info right = dfs(node->right);

        Info curr;
        curr.sum = left.sum + right.sum + node->val;

        if (left.isBST && right.isBST &&
            left.maxVal < node->val && node->val < right.minVal) {
            curr.isBST = true;
            curr.minVal = node->left ? left.minVal : node->val;
            curr.maxVal = node->right ? right.maxVal : node->val;
            if (curr.sum > maxSum) maxSum = curr.sum;
        } else {
            curr.isBST = false;
            curr.minVal = 0;
            curr.maxVal = 0;
        }
        return curr;
    }

    int maxSumBST(TreeNode* root) {
        maxSum = 0;
        dfs(root);
        return (int)maxSum;
    }
};
